import { planUpdate } from "../../src/ical/edit.js";
import { verifyPlan } from "../../src/ical/guard.js";
import { ORACLE_SEEDS } from "./corpus.js";
import { ENV, NOW, load, worldOf } from "./world.js";
import { applyPlan, standWith, storedIcs } from "./apply.js";

const seed = ORACLE_SEEDS.find((s) => s.name === "weekly-count-moscow")!;
const stand = standWith(seed);
const ics = stand.fake.ics(stand.path);
const o = load(ics);
const patch = {"recurrence":{"interval":1001}};
const plan = planUpdate(o, { now: NOW, scope: "this_and_following", instanceStart: "2026-10-19T10:00:00+03:00", patch, confirm: false, etag: undefined, currentEtag: stand.etag });
verifyPlan(ics, plan, ENV, { now: NOW, patch }); // как зовёт оркестрация: с патчем
await applyPlan(stand, plan);
console.log(worldOf(storedIcs(stand)).snaps.map((s) => s.address + " " + s.summary));
// здесь отказ invalid-rule, а правка обязана проходить: у конечной серии (COUNT или UNTIL) шаг повтора числа встреч не меняет: сколько их было, столько и останется, а последняя

